What goes wrong with this example, and why is silently retaining one duplicate ID unsafe?

```python
def outline(records):
    nodes = {r['id']: {**r, 'children': []} for r in records}
    roots = []
    for node in nodes.values():
        if node['parent_id'] is None:
            roots.append(node)
        else:
            nodes[node['parent_id']]['children'].append(node)
    return roots

records = [
    {'id': 'a', 'parent_id': None, 'title': 'A'},
    {'id': 'b', 'parent_id': 'a', 'title': 'B'},
    {'id': 'b', 'parent_id': None, 'title': 'Other B'},
]
```

Create all nodes in the first pass, rejecting duplicate IDs. In the second pass, check that each non-null parent exists before attaching the node:

```python
def outline(records):
    nodes = {}
    for record in records:
        node_id = record['id']
        if node_id in nodes:
            raise ValueError(f"Duplicate ID: {node_id!r}")
        nodes[node_id] = {**record, 'children': []}

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent_id = record['parent_id']
        if parent_id is None:
            roots.append(node)
        else:
            if parent_id not in nodes:
                raise ValueError(f"Missing parent ID: {parent_id!r}")
            nodes[parent_id]['children'].append(node)
    return roots
```

The second pass preserves input order for roots and siblings, including when a child precedes its parent. Cycle detection still needs separate validation; otherwise, cyclic nodes will not appear in the returned roots.

Walk each parent chain iteratively, keeping a set of IDs in the current chain and a set of IDs whose chains have already been validated. Reaching an ID in the current chain means a cycle; reaching a root or a completed ID means the whole current chain is valid. This checks disconnected cycles and self-cycles without rechecking completed chains.

```python
def outline(records):
    records = list(records)
    nodes = {}

    for record in records:
        node_id = record['id']
        if node_id is None:
            raise ValueError('None cannot be a record ID')
        if node_id in nodes:
            raise ValueError(f'Duplicate ID: {node_id!r}')
        nodes[node_id] = {**record, 'children': []}

    for record in records:
        parent_id = record['parent_id']
        if parent_id is not None and parent_id not in nodes:
            raise ValueError(f'Missing parent ID: {parent_id!r}')

    complete = set()
    for record in records:
        current = record['id']
        chain = set()
        while current is not None and current not in complete:
            if current in chain:
                raise ValueError(f'Cycle involving ID: {current!r}')
            chain.add(current)
            current = nodes[current]['parent_id']
        complete.update(chain)

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent_id = record['parent_id']
        if parent_id is None:
            roots.append(node)
        else:
            nodes[parent_id]['children'].append(node)
    return roots
```

For a valid chain `c → b → a → None`, all three become complete. A later chain reaching `b` stops there. Each ID enters a newly validated chain at most once, so expected time is O(n) with standard hash-table assumptions; space is O(n), including the output and validation sets. The final pass preserves root and sibling input order.

```python
import unittest


def outline(records):
    records = list(records)
    nodes = {}
    for record in records:
        node_id = record['id']
        if node_id is None:
            raise ValueError('None cannot be a record ID')
        if node_id in nodes:
            raise ValueError(f'Duplicate ID: {node_id!r}')
        nodes[node_id] = {**record, 'children': []}

    for node in nodes.values():
        parent = node['parent_id']
        if parent is not None and parent not in nodes:
            raise ValueError(f'Missing parent ID: {parent!r}')

    complete = set()
    for node_id in nodes:
        current, chain = node_id, set()
        while current is not None and current not in complete:
            if current in chain:
                raise ValueError(f'Cycle involving ID: {current!r}')
            chain.add(current)
            current = nodes[current]['parent_id']
        complete.update(chain)

    roots = []
    for record in records:
        node = nodes[record['id']]
        parent = record['parent_id']
        if parent is None:
            roots.append(node)
        else:
            nodes[parent]['children'].append(node)
    return roots


class OutlineTests(unittest.TestCase):
    def test_order_and_child_before_parent(self):
        records = [
            {'id': 'c2', 'parent_id': 'p'},
            {'id': 'r', 'parent_id': None},
            {'id': 'c1', 'parent_id': 'p'},
            {'id': 'p', 'parent_id': None},
        ]
        roots = outline(iter(records))
        self.assertEqual([n['id'] for n in roots], ['r', 'p'])
        self.assertEqual([n['id'] for n in roots[1]['children']], ['c2', 'c1'])
        self.assertNotIn('children', records[0])

    def test_invalid_inputs(self):
        record = {'id': 'a', 'parent_id': None}
        cases = [
            [record, record.copy()],
            [{'id': None, 'parent_id': None}],
            [{'id': 'a', 'parent_id': 'missing'}],
            [{'id': 'a', 'parent_id': 'a'}],
            [record, {'id': 'b', 'parent_id': 'c'},
             {'id': 'c', 'parent_id': 'b'}],
        ]
        for records in cases:
            with self.subTest(records=records), self.assertRaises(ValueError):
                outline(records)

    def test_empty_and_deep(self):
        self.assertEqual(outline([]), [])
        records = [{'id': i, 'parent_id': i - 1 if i else None}
                   for i in range(5000)]
        node = outline(records)[0]
        for i in range(5000):
            self.assertEqual(node['id'], i)
            children = node['children']
            self.assertEqual(len(children), i < 4999)
            if children:
                node = children[0]


if __name__ == '__main__':
    unittest.main()
```

Expected time and space are O(n), assuming ordinary hash-table behavior. The function makes shallow copies of records and does not mutate the input. Tests are provided but have not been run.

I’m writing a small inventory reconciler, but this gives the wrong result and changes `stock`. What’s going wrong?

```python
def reconcile(current, updates):
    for item, qty in updates.items():
        if not qty:
            current.pop(item, None)
        else:
            current[item] = qty
    return current

stock = {'pen': 2, 'tape': 1}
updates = {'pen': 0, 'tape': None}
# Expected: {'pen': 0}; stock must remain unchanged.
```

`if not qty` treats both `0` and `None` as false, so it removes both items. The function also modifies `current` directly, which changes the original `stock` dictionary.

Make a copy and check explicitly for `None`:

```python
def reconcile(current, updates):
    result = current.copy()
    for item, qty in updates.items():
        if qty is None:
            result.pop(item, None)
        else:
            result[item] = qty
    return result
```

This returns `{'pen': 0}` and leaves `stock` unchanged.

Validate the existing entries and each update, while keeping duplicate detection and patch behavior:

```python
from collections.abc import Mapping

def reconcile(current, updates):
    def validate(item, qty, *, allow_none):
        if not isinstance(item, str) or not item:
            raise ValueError(f"Invalid key: {item!r}")
        if qty is None and allow_none:
            return
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            raise ValueError(f"Invalid quantity for {item!r}: {qty!r}")

    for item, qty in current.items():
        validate(item, qty, allow_none=False)

    result = current.copy()
    seen = set()
    pairs = updates.items() if isinstance(updates, Mapping) else updates

    for item, qty in pairs:
        validate(item, qty, allow_none=True)
        if item in seen:
            raise ValueError(f"Duplicate update for {item!r}")
        seen.add(item)

        if qty is None:
            result.pop(item, None)
        else:
            result[item] = qty

    return result
```

This assumes `current` is a dictionary and updates are a mapping or well-formed iterable of pairs. It leaves `current` unchanged, including when validation fails.

```python
from collections.abc import Mapping
import unittest


def reconcile(current, updates):
    def validate(key, qty, allow_none):
        if not isinstance(key, str) or not key:
            raise ValueError('Invalid key')
        if qty is None and allow_none:
            return
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 0:
            raise ValueError('Invalid quantity')

    for key, qty in current.items():
        validate(key, qty, False)

    result = current.copy()
    seen = set()
    pairs = updates.items() if isinstance(updates, Mapping) else updates
    for key, qty in pairs:
        validate(key, qty, True)
        if key in seen:
            raise ValueError('Duplicate key')
        seen.add(key)
        if qty is None:
            result.pop(key, None)
        else:
            result[key] = qty
    return result


class ReconcileTests(unittest.TestCase):
    def test_patch_and_inputs(self):
        current = {'pen': 2, 'tape': 1, 'book': 4}
        updates = [('pen', 0), ('tape', None), ('missing', None)]
        self.assertEqual(reconcile(current, iter(updates)), {'pen': 0, 'book': 4})
        self.assertEqual(current, {'pen': 2, 'tape': 1, 'book': 4})
        self.assertEqual(updates, [('pen', 0), ('tape', None), ('missing', None)])

    def test_duplicate_and_invalid_updates_preserve_inputs(self):
        for bad in [[('pen', 1), ('pen', 1)],
                    [('pen', 1), ('', 2)], [('pen', 1), (1, 2)],
                    [('pen', 1), ('x', -1)], [('pen', 1), ('x', True)],
                    [('pen', 1), ('x', 1.5)]]:
            with self.subTest(bad=bad):
                current = {'pen': 2}
                before = bad.copy()
                with self.assertRaises(ValueError):
                    reconcile(current, bad)
                self.assertEqual(current, {'pen': 2})
                self.assertEqual(bad, before)

    def test_invalid_current(self):
        for current in ({'': 1}, {1: 1}, {'x': None}, {'x': -1},
                        {'x': False}, {'x': 1.5}):
            with self.subTest(current=current):
                before = current.copy()
                with self.assertRaises(ValueError):
                    reconcile(current, [])
                self.assertEqual(current, before)


if __name__ == '__main__':
    unittest.main()
```

